INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 43, 'theory', 'Quiz: Concurrency');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 43, 0, 'How does concurrency differ from parallelism?', '["It doesn''t", "Concurrency — tasks are interleaved, parallelism — they run at once on different cores", "Parallelism is slower", "Concurrency is only threads"]', 1, 'Concurrency is organizing several tasks; parallelism is running them at the same time.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 43, 1, 'Which tasks do threads speed up in Python?', '["Pure computation", "Waiting for I/O: network, disk, sleep", "Any", "None"]', 1, 'The GIL is released while waiting, so waits overlap; computation stays sequential.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 43, 2, 'Why is a Lock needed when several threads change a shared counter?', '["It speeds up the program", "It stops threads from overwriting each other''s changes: read-add-write is not indivisible", "It is only needed for reading", "It blocks the GIL"]', 1, 'Without a lock a race condition occurs and the counter ends up smaller than expected.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 43, 3, 'What does a Future object hold if an error occurred in the task?', '["Nothing", "The exception: it is raised when result() is called", "The value None", "A return code"]', 1, 'A future saves the exception and raises it at the place where you read the result.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 43, 4, 'What is better to choose for heavy computation on several cores?', '["Threads", "Processes (ProcessPoolExecutor)", "A queue", "An Event"]', 1, 'Each process has its own interpreter and its own GIL, so calculations really run in parallel.');
